mapper.select:
SELECT 
FROM event_dispatch_job
WHERE incident_id = #{incidentId, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND sse_sequence > #{afterSequence}
  AND sse_sequence <= #{throughSequence}
ORDER BY sse_sequence
LIMIT #{limit}

mapper.update:
UPDATE event_dispatch_job
SET sse_sequence = #{sseSequence}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND sse_sequence IS NULL
  AND dispatch_status != 'COMPLETED'

mapper.select:
UPDATE event_dispatch_job
SET dispatch_status = #{claimStatus}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND dispatch_status = 'PENDING'
RETURNING

mapper.update:
UPDATE event_dispatch_job
SET dispatch_status = #{completedStatus}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND dispatch_status = 'DISPATCHING'

UPDATE event_dispatch_job
SET dispatch_status = #{failedStatus}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND dispatch_status = 'DISPATCHING'
